mapper.select:
select instance.id, concat(instance.version,c.name,m.name,'教学大纲') as name,instance.version, instance.outline_id,outline.name outline_name,instance.college_Id,
instance.create_time, instance.creator, instance.last_modified_time, instance.last_modifier, instance.remark, instance.sysflag,instance.status status,
instance.file_id file_id,instance.download_url,instance.preview_url,instance.category_id,instance.major_id,c.name as category_name,m.name as major_name
from t_csys_teaching_programme_instance instance
left join t_csys_teaching_programme_outline outline
on instance.outline_id = outline.id
left join t_csys_training_scheme_category c on c.id=instance.category_id
left join t_csys_std_major m on m.id=instance.major_id


        and instance.name like concat('%', #{name}, '%')


        and instance.version = #{version}


        and instance.outline_id = #{outlineId}


        and instance.creator = #{creator}


        and instance.last_modified_time = #{lastModifiedTime}


        and instance.last_modifier = #{lastModifier}


        and instance.sysflag = #{sysflag}


        and instance.status = #{status}


        and instance.college_Id = #{collegeId}


        and instance.category_id = #{categoryId}


        and instance.major_id = #{majorId}




        order by ${database_prop} ${order}


        order by instance.id desc
